using AcmeStub;

var builder = WebApplication.CreateBuilder(args);

// the keys and the notification secrets arrive as files, generated by compose.yml on the first docker compose up
builder.Configuration.AddKeyPerFile("/secrets", optional: true);

builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddSingleton<Notifier>();
builder.Services.AddSingleton<Gateway>();

var app = builder.Build();

app.MapPost("/api/payment", (HttpContext context, Gateway gateway) => gateway.SubmitPaymentAsync(context));
app.MapGet("/apirttq/query/Merchant/{merchantId}", (HttpContext context, string merchantId, Gateway gateway) =>
    gateway.QueryTransaction(context, merchantId));
app.MapPost("/stub/reversals", (HttpContext context, Gateway gateway) => gateway.SendReversalAsync(context));
app.MapPost("/stub/refunds", (HttpContext context, Gateway gateway) => gateway.SendRefundAsync(context));

// made before the first request, so a missing key, secret or merchant id stops the stub at start
app.Services.GetRequiredService<Gateway>();

app.Run();
